    return [{**s, "subject": "science", "observedPattern": "公立學校公開自然／理化試題常以高度—溫度圖、天氣、臭氧、流星與極光情境考查大氣分層及溫度趨勢；本題只取能力方向並重新設計剖面、資料與選項。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


