Q = [
    make(1, "大氣分層的主要判定依據是什麼？", {"A": "每層厚度一定相同", "B": "溫度隨高度變化的趨勢", "C": "天空看起來的顏色", "D": "該層是否完全沒有氣體"}, "B", "大氣四層常依高度增加時溫度上升或下降的趨勢轉折來劃分，不是按照等距厚度硬切。", "先讀高度—溫度剖面，再找溫度趨勢的轉向。", ["確認剖面的橫軸是高度、縱軸是溫度。", "觀察每一段曲線隨高度的升降方向。", "找出下降與上升趨勢的轉折。", "層界通常畫在趨勢改變附近。", "所以分層依據是溫度隨高度的變化趨勢。"], "easy"),
    make(2, "雲、雨與多數天氣現象主要發生在哪一層？", {"A": "對流層", "B": "平流層", "C": "中氣層", "D": "增溫層"}, "A", "對流層靠近地面，空氣受熱上升、冷卻凝結，雲、雨、風和風暴等天氣主要在此發生。", "把現象與其需要的水氣、對流和高度條件配對。", ["列出天氣現象需要水氣與空氣運動。", "確認對流層最靠近地面。", "地表加熱可使空氣上升。", "上升冷卻會造成凝結和雲雨。", "因此天氣主要位於對流層。"], "easy"),
    make(3, "平流層中溫度隨高度增加而上升，常與哪項因素有關？", {"A": "臭氧吸收紫外線並造成加熱", "B": "地面海水直接沸騰", "C": "流星撞擊使整層結冰", "D": "所有氮氣消失"}, "A", "平流層的臭氧可吸收部分紫外線，能量轉換造成加熱，與該層溫度隨高度上升的趨勢有關。", "先讀圖上的溫度趨勢，再用已知的輻射吸收機制解釋，不把兩種資料混為一談。", ["辨認平流層的溫度隨高度上升。", "尋找能在高處吸收紫外線的成分。", "臭氧吸收紫外線並轉為熱能。", "這可解釋平流層的增溫趨勢。", "因此選臭氧吸收紫外線的因素。"], "medium"),
    make(4, "流星進入大氣時常在中氣層附近發光、消融，主要原因是？", {"A": "與稠密空氣作用產生摩擦與加熱", "B": "被地面燈光照亮", "C": "在真空中自動燃燒", "D": "因為中氣層完全沒有粒子"}, "A", "流星高速進入大氣，與空氣粒子碰撞造成加熱並發光、消融；中氣層是許多流星可見現象的高度線索。", "把發光現象連到高速運動與空氣粒子作用，不誤認為完全真空。", ["確認流星高速進入大氣。", "它會與沿途空氣粒子碰撞。", "碰撞與壓縮加熱使物質發光。", "部分流星物質會消融。", "因此選與空氣作用產生加熱。"], "medium"),
    make(5, "極光常與增溫層附近的高空電離區有關。下列哪項解釋較合理？", {"A": "高能太陽輻射與帶電粒子在高空作用形成發光現象", "B": "極光是對流層的普通降雨", "C": "極光只由海水反射月光造成", "D": "增溫層因粒子很多所以像高溫爐"}, "A", "增溫層的稀薄氣體可吸收高能太陽輻射，帶電粒子與高空氣體作用可產生極光；『溫度高』不等於粒子密度高。", "先定位現象高度，再區分粒子能量與粒子數量兩個概念。", ["確認極光是高空發光現象。", "增溫層與高能太陽輻射作用有關。", "帶電粒子可使稀薄氣體發光。", "高溫描述粒子平均能量，不代表粒子很多。", "所以選高能輻射與帶電粒子作用。"], "hard"),
    make(6, "若高度—溫度圖中某段曲線由『隨高度下降』轉為『隨高度上升』，層界較適合畫在哪裡？", {"A": "曲線趨勢轉折附近", "B": "圖的正中央，不論曲線如何", "C": "最低溫點以外任意位置", "D": "每隔固定 10 公里畫一次"}, "A", "大氣分層是依溫度趨勢改變的轉折建立近似界線，因此應在下降轉上升的附近判定層界。", "讀曲線的斜率變化，不用固定距離或單一極值代替趨勢判讀。", ["先觀察曲線在轉折前的方向。", "再確認轉折後方向相反。", "這表示溫度隨高度的趨勢改變。", "層界可畫在此轉向附近。", "所以選曲線趨勢轉折的位置。"], "medium"),
    make(7, "下列哪項不能只由平流層的溫度上升曲線直接推出？", {"A": "該高度範圍的溫度隨高度呈上升趨勢", "B": "平流層的分層位置可由剖面趨勢估計", "C": "臭氧在每一高度的精確濃度數值", "D": "溫度曲線與平流層特徵相符"}, "C", "溫度曲線可支持趨勢與分層判讀，但臭氧精確濃度需要另外的成分觀測；不能只由溫度曲線讀出臭氧量。", "分辨剖面直接提供的溫度證據與需要其他儀器的成分資料。", ["列出圖表直接量到的是溫度。", "可由曲線讀出隨高度上升的趨勢。", "可用趨勢估計平流層的模型範圍。", "臭氧濃度是另一種資料。", "因此不能直接推出臭氧的精確數值。"], "hard"),
    make(8, "對流層溫度通常隨高度增加而降低，哪個機制較能解釋？", {"A": "地表受熱後空氣上升膨脹冷卻，對流層越高通常越冷", "B": "越高處一定有更多地面熱源", "C": "雲會把所有熱量變成氧氣", "D": "高空完全沒有空氣所以不需解釋"}, "A", "地表是對流層主要熱源，空氣受熱上升後膨脹冷卻，形成對流層常見的高度降溫趨勢。", "把地表加熱、空氣上升與膨脹冷卻串成因果鏈。", ["確認對流層受地表加熱影響。", "暖空氣上升進入較低壓環境。", "上升膨脹會使空氣冷卻。", "高度增加時溫度因此常下降。", "所以選地表加熱與上升冷卻的機制。"], "medium"),
    make(9, "說『增溫層溫度很高』時，為何不能直接推論人在那裡會感到像火爐一樣炎熱？", {"A": "高溫代表粒子平均能量高，但氣體極稀薄、碰撞傳熱很少", "B": "增溫層完全沒有任何粒子", "C": "溫度在任何地方都沒有意義", "D": "高空一定比地面有更多液態水"}, "A", "增溫層粒子可因吸收高能輻射而有很高平均能量，但粒子數量極少，與人體碰撞傳遞的總熱量未必像稠密高溫環境。", "區分微觀溫度與宏觀熱傳遞，不能只用『高溫』一詞類比地面環境。", ["確認溫度描述粒子平均動能。", "增溫層的粒子平均能量可很高。", "但粒子密度很低，碰撞次數少。", "人體感受的熱量還取決於碰撞與能量傳遞。", "所以不能直接類比成地面火爐。"], "hard"),
    make(10, "把大氣分成四層時，最適當的科學表述是？", {"A": "四層是依溫度趨勢建立的方便模型，實際成分與狀態仍連續變化", "B": "四層之間有絕對硬牆，氣體不能跨越", "C": "每層厚度永遠固定且全球相同", "D": "只要知道層名就能推出所有天氣與成分資料"}, "A", "四層模型方便描述溫度隨高度的趨勢和相關現象，但實際大氣的壓力、成分與活動是連續變化，層界不是絕對硬牆。", "回答模型題時同時說明模型能解釋的範圍與近似限制。", ["確認四層是由溫度剖面建立的分類模型。", "模型可協助定位天氣、臭氧、流星與極光。", "實際大氣成分與壓力會連續變化。", "層界不是所有情況都固定不變的硬牆。", "因此選能兼顧用途與限制的表述。"], "hard"),
]

